examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
    Column(
        modifier = Modifier.fillMaxWidth(),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
    ) {
        MonarchAvatar(
            image = null,
            name = {{app.name}},
            shape = MonarchAvatarShape.Square,
            size = MonarchAvatarSize.Lg,
            decorative = true,
        )
        MonarchText(
            text = {{app.name}} + " wants to access your account",
            style = MonarchTextStyle.Heading,
            heading = true,
            textAlign = TextAlign.Center,
        )
        MonarchText(text = {{app.domain}}, color = MonarchTheme.colors.textMuted, textAlign = TextAlign.Center)
        if (verified) {
            MonarchBadge(text = "Verified", tone = MonarchTone.Success)
        }
    }
    MonarchCard {
        Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
            Row(
                horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                MonarchAvatar(image = null, name = {{account.name}}, decorative = true)
                Column(modifier = Modifier.weight(1f)) {
                    MonarchText(text = {{account.name}}, style = MonarchTextStyle.BodyStrong)
                    MonarchText(text = {{account.email}}, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
                }
            }
            MonarchButton(
                text = "Use another account",
                onClick = {},
                modifier = Modifier.align(Alignment.End),
                variant = MonarchButtonVariant.Ghost,
                size = MonarchButtonSize.Sm,
            )
        }
    }
    Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        MonarchText(text = {{app.name}} + " will be able to:", style = MonarchTextStyle.Label)
        scopes.forEach { scope ->
            val sensitive = scope.kind == MonarchConsequenceKind.Warning
            Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                MonarchIcon(
                    SampleIcons.Check,
                    contentDescription = if (sensitive) "Sensitive" else "Allowed",
                    size = MonarchIconSize.Sm,
                    tint = if (sensitive) MonarchTheme.colors.warningStrong else MonarchTheme.colors.successStrong,
                )
                Column {
                    MonarchText(text = scope.label, style = if (sensitive) MonarchTextStyle.BodyStrong else MonarchTextStyle.Body)
                    scope.detail?.let {
                        MonarchText(text = it, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
                    }
                }
            }
        }
    }
    Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
        MonarchButton(
            text = "Cancel",
            onClick = { denying = true },
            modifier = Modifier.weight(1f),
            size = MonarchButtonSize.Lg,
            enabled = !allowing,
            loading = denying,
        )
        MonarchButton(
            text = "Allow",
            onClick = { allowing = true },
            modifier = Modifier.weight(1f),
            variant = MonarchButtonVariant.Primary,
            size = MonarchButtonSize.Lg,
            enabled = !denying,
            loading = allowing,
        )
    }
    MonarchText(text = legal, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted, textAlign = TextAlign.Center)
    MonarchText(text = {{footnote}}, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
}

examples.setupTemplate:
// Whether the identity provider has verified the app.
val verified = {{app.verified}}
var allowing by remember { mutableStateOf(false) }
var denying by remember { mutableStateOf(false) }
val links = MonarchLinkDefaults.styles()
val legal = buildAnnotatedString {
    append("Before you continue, read " + {{app.name}} + "’s ")
    withLink(LinkAnnotation.Url({{app.privacyUrl}}, links)) { append("privacy policy") }
    append(" and ")
    withLink(LinkAnnotation.Url({{app.termsUrl}}, links)) { append("terms") }
    append(".")
}
val scopes = listOf(
    MonarchConsequence(MonarchConsequenceKind.{{scopes.0.kind|pascal}}, {{scopes.0.label}}),
    MonarchConsequence(MonarchConsequenceKind.{{scopes.1.kind|pascal}}, {{scopes.1.label}}),
    MonarchConsequence(
        // The web draws a check for every scope; the sensitive one is amber and bold, with its note under it.
        MonarchConsequenceKind.Warning,
        {{scopes.2.label}},
        detail = {{scopes.2.description}},
    ),
)

examples.setup:
// Whether the identity provider has verified the app.
val verified = true
var allowing by remember { mutableStateOf(false) }
var denying by remember { mutableStateOf(false) }
val links = MonarchLinkDefaults.styles()
val legal = buildAnnotatedString {
    append("Before you continue, read " + "Example Notes" + "’s ")
    withLink(LinkAnnotation.Url("https://notes.example.com/privacy", links)) { append("privacy policy") }
    append(" and ")
    withLink(LinkAnnotation.Url("https://notes.example.com/terms", links)) { append("terms") }
    append(".")
}
val scopes = listOf(
    MonarchConsequence(MonarchConsequenceKind.Kept, "See your name and profile photo"),
    MonarchConsequence(MonarchConsequenceKind.Kept, "See your email address"),
    MonarchConsequence(
        // The web draws a check for every scope; the sensitive one is amber and bold, with its note under it.
        MonarchConsequenceKind.Warning,
        "Create and change files in your workspace",
        detail = "Only in the workspace you choose.",
    ),
)

